#!/usr/bin/env python3
"""Sample JSONL data using different strategies: random, stratified, systematic."""

import argparse
import json
import random
import sys
from collections import Counter
from pathlib import Path


def load_jsonl(path):
    with open(path, "r", encoding="utf-8") as f:
        return [json.loads(line) for line in f if line.strip()]


def write_jsonl(records, path):
    with open(path, "w", encoding="utf-8") as f:
        for rec in records:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")


def sample_random(records, n, seed=None):
    rng = random.Random(seed)
    if n >= len(records):
        return list(records)
    return rng.sample(records, n)


def sample_stratified(records, n, key, seed=None):
    rng = random.Random(seed)
    groups = {}
    for rec in records:
        groups.setdefault(rec.get(key), []).append(rec)

    total = len(records)
    result = []
    remaining = n

    group_keys = list(groups.keys())
    allocated = {}
    for gk in group_keys:
        proportion = len(groups[gk]) / total
        alloc = round(n * proportion)
        allocated[gk] = min(alloc, len(groups[gk]))

    # Adjust for rounding errors
    diff = n - sum(allocated.values())
    for gk in rng.sample(group_keys, len(group_keys)):
        if diff == 0:
            break
        headroom = len(groups[gk]) - allocated[gk]
        if diff > 0 and headroom > 0:
            add = min(diff, headroom)
            allocated[gk] += add
            diff -= add
        elif diff < 0 and allocated[gk] > 0:
            remove = min(-diff, allocated[gk])
            allocated[gk] -= remove
            diff += remove

    for gk, count in allocated.items():
        result.extend(rng.sample(groups[gk], count))

    rng.shuffle(result)
    return result


def sample_systematic(records, n, seed=None):
    if n >= len(records):
        return list(records)
    rng = random.Random(seed)
    start = rng.randint(0, len(records) - 1)
    step = len(records) / n
    indices = [(start + int(i * step)) % len(records) for i in range(n)]
    return [records[i] for i in sorted(set(indices))]


STRATEGIES = {
    "random": sample_random,
    "stratified": sample_stratified,
    "systematic": sample_systematic,
}


def main():
    parser = argparse.ArgumentParser(description="Sample JSONL data.")
    parser.add_argument("input", help="Path to input JSONL file")
    parser.add_argument("-o", "--output", help="Output JSONL path (default: stdout)")
    parser.add_argument("-n", "--num", type=int, required=True, help="Number of samples")
    parser.add_argument(
        "-s",
        "--strategy",
        choices=STRATEGIES.keys(),
        default="random",
        help="Sampling strategy (default: random)",
    )
    parser.add_argument(
        "-k", "--key", help="Field key for stratified sampling (required for stratified)"
    )
    parser.add_argument("--seed", type=int, default=None, help="Random seed")
    args = parser.parse_args()

    if args.strategy == "stratified" and not args.key:
        parser.error("--key is required for stratified sampling")

    records = load_jsonl(args.input)
    if args.num > len(records):
        print(
            f"Warning: requested {args.num} but only {len(records)} records available",
            file=sys.stderr,
        )

    if args.strategy == "stratified":
        result = sample_stratified(records, args.num, args.key, args.seed)
    else:
        result = STRATEGIES[args.strategy](records, args.num, args.seed)

    if args.output:
        write_jsonl(result, args.output)
        print(f"Wrote {len(result)} records to {args.output}", file=sys.stderr)
    else:
        for rec in result:
            print(json.dumps(rec, ensure_ascii=False))


if __name__ == "__main__":
    main()
